# Tests for `src/core/types.jl`.
#
# The file defines the model type hierarchy of the package: one abstract root
# (`AbstractBFModelEdisgo`) below PowerModels' `AbstractBFQPModel`, a base concrete
# model, and one abstract/concrete pair per formulation (SOC relaxation and
# non-convex). The types carry no behaviour of their own — what they do is select
# methods — so the tests check the hierarchy, the fields generated by
# PowerModels' `@pm_fields` macro, instantiability, the exported API, and that the
# dispatch actually picks the intended `constraint_model_current` method.

include(joinpath(@__DIR__, "..", "testsetup.jl"))

# Field names generated by PowerModels' `@pm_fields` macro. Every concrete model
# type of the package carries exactly these, in this order.
const TYPES_PM_FIELDS = (:model, :data, :setting, :solution, :ref, :var, :con,
                         :sol, :sol_proc, :ext)

"""
Instantiate model type `T` on the small fixture network with a build method that
adds nothing. Isolates the type itself from the problem formulation, so that even
model types without a complete set of `constraint_*` methods can be created.
"""
types_bare_model(T::Type) = eDisGo_OPF.instantiate_model(
    TestUtils.multinetwork(TestUtils.small_network()), T, _pm -> nothing)

"Assert that concrete model type `T` looks like a PowerModels model type."
function types_check_pm_fields(T::Type)
    @test isconcretetype(T)
    @test ismutabletype(T)
    @test fieldnames(T) === TYPES_PM_FIELDS
    # `@pm_fields` fixes the field types as well; `ref`/`var`/`con`/`sol`/
    # `sol_proc`/`ext` are keyed by Symbol, the data-side dicts by String.
    # (`==`, not `===`: `Dict{String}` is a `UnionAll`, and two separately built
    # `UnionAll`s are equal but not identical.)
    @test fieldtype(T, :model) === JuMP.AbstractModel
    for f in (:data, :setting, :solution)
        @test fieldtype(T, f) == Dict{String}
    end
    for f in (:ref, :var, :con, :sol, :sol_proc, :ext)
        @test fieldtype(T, f) == Dict{Symbol}
    end
    # The generated inner constructor takes the ten fields positionally.
    @test length(first(methods(T)).sig.parameters) == length(TYPES_PM_FIELDS) + 1
end

"Assert that `pm` is a usable, freshly instantiated model of type `T`."
function types_check_instance(pm, T::Type)
    @test pm isa T
    @test pm isa eDisGo_OPF.AbstractBFModelEdisgo
    @test pm.model isa JuMP.Model
    # Nothing was built, so the JuMP model is still empty …
    @test JuMP.num_variables(pm.model) == 0
    @test TestUtils.num_constraints_total(pm.model) == 0
    # … but the data and the reference dict of the two time steps are in place.
    @test sort(collect(keys(pm.data["nw"]))) == ["1", "2"]
    @test sort(collect(keys(PowerModels.nws(pm)))) == [1, 2]
    @test PowerModels.ref(pm, 1, :opf_version) == 2
    @test length(PowerModels.ref(pm, 1, :branch)) == 3
    for f in (:var, :con, :sol, :sol_proc, :ext)
        @test getfield(pm, f) isa Dict{Symbol,<:Any}
    end
end

@testset "AbstractBFModelEdisgo" begin
    T = eDisGo_OPF.AbstractBFModelEdisgo

    @test isabstracttype(T)
    # Direct extension of PowerModels' quadratic branch-flow model, and therefore
    # of everything above it.
    @test supertype(T) === PowerModels.AbstractBFQPModel
    @test T <: PowerModels.AbstractBFQPModel
    @test T <: PowerModels.AbstractBFModel
    @test T <: PowerModels.AbstractPowerModel
    @test T <: InfrastructureModels.AbstractInfrastructureModel
    # It is *not* one of the other PowerModels families: neither a bus-injection
    # formulation nor the conic variant of the branch-flow model.
    @test !(T <: PowerModels.AbstractACPModel)
    @test !(T <: PowerModels.AbstractDCPModel)
    @test !(T <: PowerModels.AbstractBFConicModel)

    # All model types of the package hang below it.
    for S in (eDisGo_OPF.BFPowerModelEdisgo, eDisGo_OPF.AbstractSOCBFModelEdisgo,
              eDisGo_OPF.SOCBFPowerModelEdisgo, eDisGo_OPF.AbstractNCBFModelEdisgo,
              eDisGo_OPF.NCBFPowerModelEdisgo)
        @test S <: T
    end

    # Abstract types cannot be instantiated.
    @test_throws MethodError T()

    # It is the dispatch anchor of the problem formulation: the build method is
    # defined once, for the abstract root, and inherited by all three model types.
    for S in (eDisGo_OPF.BFPowerModelEdisgo, eDisGo_OPF.SOCBFPowerModelEdisgo,
              eDisGo_OPF.NCBFPowerModelEdisgo)
        @test which(eDisGo_OPF.build_mn_opf_bf_flex, Tuple{S}).sig.parameters[2] === T
    end

    # Internal: only the three concrete types are exported (see test_smoke.jl).
    @test isdefined(eDisGo_OPF, :AbstractBFModelEdisgo)
    @test !(:AbstractBFModelEdisgo in names(eDisGo_OPF))
end

@testset "BFPowerModelEdisgo" begin
    T = eDisGo_OPF.BFPowerModelEdisgo

    @test supertype(T) === eDisGo_OPF.AbstractBFModelEdisgo
    # Base type: it is neither of the two formulations.
    @test !(T <: eDisGo_OPF.AbstractSOCBFModelEdisgo)
    @test !(T <: eDisGo_OPF.AbstractNCBFModelEdisgo)

    types_check_pm_fields(T)

    # Part of the public API and reachable unqualified through `using eDisGo_OPF`.
    @test :BFPowerModelEdisgo in names(eDisGo_OPF)
    @test BFPowerModelEdisgo === T

    pm = types_bare_model(T)
    types_check_instance(pm, T)

    # The base type carries the shared structure only: it fixes no coupling
    # between power, current and voltage, so `constraint_model_current` — and with
    # it the full problem formulation — has no method for it. One of the two
    # subtypes has to be used to actually build a model.
    @test_throws MethodError eDisGo_OPF.constraint_model_current(pm, 1)
    @test_throws MethodError eDisGo_OPF.instantiate_model(
        TestUtils.multinetwork(TestUtils.small_network()), T,
        eDisGo_OPF.build_mn_opf_bf_flex)
end
